/* ---------------------------------------------------------
   IMAGE WITH FALLBACK
--------------------------------------------------------- */
function ArtImage({ sources, alt, natural }) {
  const list = Array.isArray(sources) ? sources.filter(Boolean) : [sources];
  const [i, setI] = useState(0);

  if (i >= list.length) {
    return (
      <div
        style={{
          aspectRatio: natural ? undefined : "1 / 1",
          minHeight: natural ? 240 : undefined,
          background: "#E3DCCB",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          color: "#A79A85",
        }}
      >
        <ImageOff size={22} />
      </div>
    );
  }
  return (
    <img
      key={list[i]}
      src={list[i]}
      alt={alt}
      loading="lazy"
      onError={() => setI((n) => n + 1)}
      style={
        natural
          ? { width: "100%", maxHeight: "70vh", objectFit: "contain", display: "block", background: "#E3DCCB" }
          : { width: "100%", aspectRatio: "1 / 1", objectFit: "cover", display: "block", background: "#E3DCCB" }
      }
    />
  );
}

