/* ---------------------------------------------------------
   GALLERY (shared by Gallery + Selected pages)
--------------------------------------------------------- */
function sortMixed(values) {
  const nums = [];
  const words = [];
  values.forEach((v) => {
    if (/^\d+$/.test(v)) nums.push(v);
    else words.push(v);
  });
  nums.sort((a, b) => Number(a) - Number(b));
  words.sort((a, b) => a.localeCompare(b, "he"));
  return [...nums, ...words];
}

/* ---------------------------------------------------------
   MULTI-SELECT DROPDOWN (checkbox list)
--------------------------------------------------------- */
function MultiSelectFilter({ label, options, selected, setSelected, labelFor }) {
  const [open, setOpen] = useState(false);
  const ref = useRef(null);
  const { t, bodyFont } = useLang();
  const displayLabel = labelFor || ((v) => v);

  useEffect(() => {
    function handleClick(e) {
      if (ref.current && !ref.current.contains(e.target)) setOpen(false);
    }
    document.addEventListener("mousedown", handleClick);
    return () => document.removeEventListener("mousedown", handleClick);
  }, []);

  // Drop any selected values that are no longer valid options (cascading)
  useEffect(() => {
    const optionSet = new Set(options);
    const stillValid = selected.filter((s) => optionSet.has(s));
    if (stillValid.length !== selected.length) setSelected(stillValid);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [options.join("|")]);

  const toggle = (opt) => {
    setSelected((prev) => (prev.includes(opt) ? prev.filter((v) => v !== opt) : [...prev, opt]));
  };

  const buttonStyle = {
    fontFamily: bodyFont,
    fontSize: 13,
    padding: "9px 10px",
    background: "#F7F3EA",
    border: "1px solid #C9BFA9",
    color: selected.length ? "#221D17" : "#8A7E6C",
    borderRadius: 2,
    width: "100%",
    textAlign: "right",
    cursor: "pointer",
    display: "flex",
    justifyContent: "space-between",
    alignItems: "center",
    opacity: options.length ? 1 : 0.5,
  };

  return (
    <div ref={ref} style={{ position: "relative" }}>
      <button type="button" style={buttonStyle} disabled={!options.length} onClick={() => setOpen((o) => !o)}>
        <span>{selected.length ? `${label} (${selected.length})` : label}</span>
        <span style={{ fontSize: 10, color: "#A66B33" }}>▾</span>
      </button>
      {open && (
        <div
          style={{
            position: "absolute",
            top: "calc(100% + 4px)",
            right: 0,
            left: 0,
            zIndex: 30,
            background: "#F7F3EA",
            border: "1px solid #C9BFA9",
            borderRadius: 2,
            maxHeight: 260,
            overflowY: "auto",
            boxShadow: "0 6px 18px #00000022",
          }}
        >
          {selected.length > 0 && (
            <button
              type="button"
              onClick={() => setSelected([])}
              style={{
                width: "100%",
                textAlign: "right",
                background: "none",
                border: "none",
                borderBottom: "1px solid #C9BFA9",
                padding: "8px 10px",
                fontFamily: bodyFont,
                fontSize: 12,
                color: "#8B4A3D",
                cursor: "pointer",
              }}
            >
              {t("clearSelection")}
            </button>
          )}
          {options.map((opt) => (
            <label
              key={opt}
              style={{
                display: "flex",
                alignItems: "center",
                gap: 8,
                padding: "8px 10px",
                fontFamily: bodyFont,
                fontSize: 13,
                color: "#221D17",
                cursor: "pointer",
              }}
            >
              <input type="checkbox" checked={selected.includes(opt)} onChange={() => toggle(opt)} />
              {displayLabel(opt)}
            </label>
          ))}
          {options.length === 0 && (
            <div style={{ padding: "10px", fontFamily: bodyFont, fontSize: 12, color: "#8A7E6C" }}>
              {t("noOptions")}
            </div>
          )}
        </div>
      )}
    </div>
  );
}

/* ---------------------------------------------------------
   DUAL RANGE SLIDER (drag both ends)
--------------------------------------------------------- */
function DualRangeSlider({ min, max, step, value, onChange, format }) {
  const [localMin, localMax] = value;

  const handleMinChange = (e) => {
    const v = Math.min(Number(e.target.value), localMax);
    onChange([v, localMax]);
  };
  const handleMaxChange = (e) => {
    const v = Math.max(Number(e.target.value), localMin);
    onChange([localMin, v]);
  };

  const range = Math.max(max - min, 1);
  const pctMin = ((localMin - min) / range) * 100;
  const pctMax = ((localMax - min) / range) * 100;

  return (
    <div dir="ltr" style={{ position: "relative", paddingTop: 4 }}>
      <div style={{ position: "relative", height: 4, background: "#C9BFA9", borderRadius: 2, margin: "14px 8px" }}>
        <div
          style={{
            position: "absolute",
            top: 0,
            bottom: 0,
            right: `${100 - pctMax}%`,
            left: `${pctMin}%`,
            background: "#3E4A3B",
            borderRadius: 2,
          }}
        />
        <input
          type="range"
          min={min}
          max={max}
          step={step}
          value={localMin}
          onChange={handleMinChange}
          className="range-thumb"
          style={{ position: "absolute", top: -14, right: -8, left: -8, width: "calc(100% + 16px)", margin: 0, background: "transparent", pointerEvents: "none" }}
        />
        <input
          type="range"
          min={min}
          max={max}
          step={step}
          value={localMax}
          onChange={handleMaxChange}
          className="range-thumb"
          style={{ position: "absolute", top: -14, right: -8, left: -8, width: "calc(100% + 16px)", margin: 0, background: "transparent", pointerEvents: "none" }}
        />
      </div>
      <div style={{ display: "flex", justifyContent: "space-between", fontFamily: "'Roboto Mono', monospace", fontSize: 11, color: "#221D17" }}>
        <span>{format ? format(localMin) : localMin}</span>
        <span>{format ? format(localMax) : localMax}</span>
      </div>
    </div>
  );
}

/* ---------------------------------------------------------
   GALLERY
--------------------------------------------------------- */
function Gallery({ artworks, title, intro, pageKey, initialArtworkId }) {
  const { t, tv, lang, bodyFont, displayFont } = useLang();
  const [numQuery, setNumQuery] = useState("");
  const [titleQuery, setTitleQuery] = useState("");
  const [subjects, setSubjects] = useState([]);
  const [clusters, setClusters] = useState([]);
  const [techniques, setTechniques] = useState([]);
  const [sizeCats, setSizeCats] = useState([]);
  const [active, setActive] = useState(null);

  useEffect(() => {
    if (initialArtworkId) {
      const found = artworks.find((a) => a.id === initialArtworkId);
      if (found) setActive(found);
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  const select = (art) => {
    setActive(art);
    if (pageKey) window.history.replaceState(null, "", `#/${pageKey}/${art.id}`);
  };
  const closeActive = () => {
    setActive(null);
    if (pageKey) window.history.replaceState(null, "", `#/${pageKey}`);
  };

  const yearBounds = useMemo(() => {
    const vals = artworks.map((a) => a.yearNum).filter((v) => v != null);
    return vals.length ? [Math.min(...vals), Math.max(...vals)] : [1940, 2016];
  }, [artworks]);
  const lengthBounds = useMemo(() => {
    const vals = artworks.map((a) => a.dimLength).filter((v) => v != null);
    return vals.length ? [0, Math.ceil(Math.max(...vals))] : [0, 150];
  }, [artworks]);
  const widthBounds = useMemo(() => {
    const vals = artworks.map((a) => a.dimWidth).filter((v) => v != null);
    return vals.length ? [0, Math.ceil(Math.max(...vals))] : [0, 150];
  }, [artworks]);

  const [yearRange, setYearRange] = useState(yearBounds);
  const [lengthRange, setLengthRange] = useState(lengthBounds);
  const [widthRange, setWidthRange] = useState(widthBounds);

  // predicate for each filter, so we can compute cascading options by
  // applying "all filters except this one"
  const predicates = {
    subjects: (a) => !subjects.length || subjects.includes(a.subject),
    clusters: (a) => !clusters.length || clusters.includes(a.techniqueCluster),
    techniques: (a) => !techniques.length || techniques.includes(a.technique),
    sizeCats: (a) => !sizeCats.length || sizeCats.includes(a.sizeCat),
    year: (a) => a.yearNum == null || (a.yearNum >= yearRange[0] && a.yearNum <= yearRange[1]),
    length: (a) => a.dimLength == null || (a.dimLength >= lengthRange[0] && a.dimLength <= lengthRange[1]),
    width: (a) => a.dimWidth == null || (a.dimWidth >= widthRange[0] && a.dimWidth <= widthRange[1]),
    num: (a) => !numQuery || a.id.includes(numQuery.trim()),
    title: (a) => !titleQuery || a.title.includes(titleQuery),
  };
  const allKeys = Object.keys(predicates);

  function subsetExcept(exceptKey) {
    return artworks.filter((a) => allKeys.every((k) => k === exceptKey || predicates[k](a)));
  }

  const filtered = useMemo(() => subsetExcept(null), [
    artworks, subjects, clusters, techniques, sizeCats, yearRange, lengthRange, widthRange, numQuery, titleQuery,
  ]);

  const subjectOptions = useMemo(
    () => Array.from(new Set(subsetExcept("subjects").map((a) => a.subject))).sort((a, b) => a.localeCompare(b, "he")),
    [artworks, clusters, techniques, sizeCats, yearRange, lengthRange, widthRange, numQuery, titleQuery]
  );
  const clusterOptions = useMemo(
    () => Array.from(new Set(subsetExcept("clusters").map((a) => a.techniqueCluster))).sort((a, b) => a.localeCompare(b, "he")),
    [artworks, subjects, techniques, sizeCats, yearRange, lengthRange, widthRange, numQuery, titleQuery]
  );
  const techniqueOptions = useMemo(
    () => Array.from(new Set(subsetExcept("techniques").map((a) => a.technique))).sort((a, b) => a.localeCompare(b, "he")),
    [artworks, subjects, clusters, sizeCats, yearRange, lengthRange, widthRange, numQuery, titleQuery]
  );
  const sizeCatOptions = useMemo(() => {
    const order = ["קטן מאוד", "קטן", "בינוני", "גדול", "גדול מאוד", "ענק"];
    const present = Array.from(new Set(subsetExcept("sizeCats").map((a) => a.sizeCat).filter(Boolean)));
    present.sort((a, b) => order.indexOf(a) - order.indexOf(b));
    return present;
  }, [artworks, subjects, clusters, techniques, yearRange, lengthRange, widthRange, numQuery, titleQuery]);

  const hasActiveFilters =
    numQuery || titleQuery || subjects.length || clusters.length || techniques.length || sizeCats.length ||
    yearRange[0] !== yearBounds[0] || yearRange[1] !== yearBounds[1] ||
    lengthRange[0] !== lengthBounds[0] || lengthRange[1] !== lengthBounds[1] ||
    widthRange[0] !== widthBounds[0] || widthRange[1] !== widthBounds[1];

  const clearAll = () => {
    setNumQuery(""); setTitleQuery("");
    setSubjects([]); setClusters([]); setTechniques([]); setSizeCats([]);
    setYearRange(yearBounds); setLengthRange(lengthBounds); setWidthRange(widthBounds);
  };

  const selectStyle = {
    fontFamily: bodyFont,
    fontSize: 13,
    padding: "9px 10px",
    background: "#F7F3EA",
    border: "1px solid #C9BFA9",
    color: "#221D17",
    borderRadius: 2,
    width: "100%",
  };
  const labelStyle = {
    fontFamily: bodyFont,
    fontSize: 11,
    color: "#8A7E6C",
    marginBottom: 4,
    display: "block",
  };

  const multiFields = [
    [t("filterSubject"), subjects, setSubjects, subjectOptions, (v) => tv(SUBJECT_TR, v)],
    [t("filterClusters"), clusters, setClusters, clusterOptions, (v) => tv(CLUSTER_TR, v)],
    [t("filterTechniques"), techniques, setTechniques, techniqueOptions, null],
    [t("filterSizeCat"), sizeCats, setSizeCats, sizeCatOptions, (v) => tv(SIZECAT_TR, v)],
  ];

  return (
    <div style={{ maxWidth: 1100, margin: "0 auto", padding: "48px 24px 100px" }}>
      <h2 style={{ fontFamily: displayFont, fontSize: 32, fontWeight: 700, color: "#221D17", margin: "0 0 8px" }}>{title}</h2>
      {intro && <p style={{ fontFamily: bodyFont, fontSize: 15, color: "#5F5449", maxWidth: 600, marginBottom: 26 }}>{intro}</p>}

      <div style={{ padding: "18px 0", borderTop: "1px solid #C9BFA9", borderBottom: "1px solid #C9BFA9", marginBottom: 32 }}>
        <div style={{ display: "flex", gap: 14, flexWrap: "wrap", marginBottom: 14 }}>
          <div>
            <label style={labelStyle}>{t("searchTitle")}</label>
            <input
              value={titleQuery}
              onChange={(e) => setTitleQuery(e.target.value)}
              placeholder={t("searchTitlePlaceholder")}
              style={{ ...selectStyle, maxWidth: 240 }}
            />
          </div>
          <div>
            <label style={labelStyle}>{t("searchNumber")}</label>
            <input
              value={numQuery}
              onChange={(e) => setNumQuery(e.target.value.replace(/[^0-9]/g, ""))}
              placeholder={t("searchNumberPlaceholder")}
              style={{ ...selectStyle, maxWidth: 160, fontFamily: "'Roboto Mono', monospace" }}
            />
          </div>
        </div>

        <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fill, minmax(160px, 1fr))", gap: 14, marginBottom: 20 }}>
          {multiFields.map(([label, selected, setSelected, options, labelFor]) => (
            <div key={label}>
              <label style={labelStyle}>{label}</label>
              <MultiSelectFilter label={label} options={options} selected={selected} setSelected={setSelected} labelFor={labelFor} />
            </div>
          ))}
        </div>

        <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fill, minmax(220px, 1fr))", gap: 24 }}>
          <div>
            <label style={labelStyle}>{t("filterYear")}</label>
            <DualRangeSlider min={yearBounds[0]} max={yearBounds[1]} step={1} value={yearRange} onChange={setYearRange} />
          </div>
          <div>
            <label style={labelStyle}>{t("filterLength")}</label>
            <DualRangeSlider min={lengthBounds[0]} max={lengthBounds[1]} step={1} value={lengthRange} onChange={setLengthRange} format={(v) => `${v} ${lang === "he" ? "ס\"מ" : "cm"}`} />
          </div>
          <div>
            <label style={labelStyle}>{t("filterWidth")}</label>
            <DualRangeSlider min={widthBounds[0]} max={widthBounds[1]} step={1} value={widthRange} onChange={setWidthRange} format={(v) => `${v} ${lang === "he" ? "ס\"מ" : "cm"}`} />
          </div>
        </div>

        <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", marginTop: 18 }}>
          <div style={{ fontFamily: "'Roboto Mono', monospace", fontSize: 11, color: "#A66B33" }}>
            {filtered.length} / {artworks.length}
          </div>
          {hasActiveFilters && (
            <button
              onClick={clearAll}
              style={{ background: "none", border: "none", cursor: "pointer", fontFamily: bodyFont, fontSize: 12, color: "#8B4A3D", textDecoration: "underline" }}
            >
              {t("clearFilters")}
            </button>
          )}
        </div>
      </div>

      <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fill, minmax(220px, 1fr))", gap: "40px 28px" }}>
        {filtered.map((art) => (
          <Placard key={art.id} art={art} onClick={() => select(art)} />
        ))}
      </div>
      {filtered.length === 0 && (
        <div style={{ fontFamily: bodyFont, color: "#6B5B4F", padding: "40px 0" }}>{t("noResults")}</div>
      )}
      <Lightbox
        art={active}
        onClose={closeActive}
        onNext={active ? () => {
          const idx = filtered.findIndex((a) => a.id === active.id);
          if (idx !== -1) select(filtered[(idx + 1) % filtered.length]);
        } : null}
        onPrev={active ? () => {
          const idx = filtered.findIndex((a) => a.id === active.id);
          if (idx !== -1) select(filtered[(idx - 1 + filtered.length) % filtered.length]);
        } : null}
      />
    </div>
  );
}


