/* ---------------------------------------------------------
   SELECTED WORKS (grouped by decade, no filters)
--------------------------------------------------------- */
function SelectedWorks({ initialArtworkId }) {
  const { t, displayFont, bodyFont, lang } = useLang();
  const [active, setActive] = useState(null);

  const decades = Object.keys(DECADE_SELECTION)
    .map(Number)
    .sort((a, b) => b - a);

  const decadeSuffix = lang === "he" ? "" : "s"; // 1960s in en/es, שנות ה-60 in he

  const allWorks = decades.flatMap((decade) =>
    DECADE_SELECTION[decade].map((id) => ARTWORKS.find((a) => a.id === id)).filter(Boolean)
  );

  useEffect(() => {
    if (initialArtworkId) {
      const found = allWorks.find((a) => a.id === initialArtworkId);
      if (found) setActive(found);
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  const select = (art) => {
    setActive(art);
    window.history.replaceState(null, "", `#/selected/${art.id}`);
  };
  const closeActive = () => {
    setActive(null);
    window.history.replaceState(null, "", `#/selected`);
  };

  return (
    <div style={{ maxWidth: 1100, margin: "0 auto", padding: "48px 24px 100px" }}>
      <h2 style={{ fontFamily: displayFont, fontSize: 32, fontWeight: 700, color: "#221D17", margin: "0 0 8px" }}>
        {t("selectedTitle")}
      </h2>
      <p style={{ fontFamily: bodyFont, fontSize: 15, color: "#5F5449", maxWidth: 600, marginBottom: 40 }}>
        {t("selectedIntro")}
      </p>

      {decades.map((decade) => {
        const ids = DECADE_SELECTION[decade];
        const works = ids.map((id) => ARTWORKS.find((a) => a.id === id)).filter(Boolean);
        if (!works.length) return null;
        const heYear = decade >= 2000 ? decade : decade % 100;
        const label = lang === "he" ? `${t("decadeLabel")}${heYear}` : `${t("decadeLabel")} ${decade}${decadeSuffix}`;
        return (
          <div key={decade} style={{ marginBottom: 48 }}>
            <div
              style={{
                fontFamily: "'Roboto Mono', monospace",
                fontSize: 13,
                letterSpacing: "0.06em",
                color: "#A66B33",
                borderBottom: "1px solid #C9BFA9",
                paddingBottom: 8,
                marginBottom: 20,
              }}
            >
              {label}
            </div>
            <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fill, minmax(220px, 1fr))", gap: "40px 28px" }}>
              {works.map((art) => (
                <Placard key={art.id} art={art} onClick={() => select(art)} />
              ))}
            </div>
          </div>
        );
      })}

      <Lightbox
        art={active}
        onClose={closeActive}
        onNext={active ? () => {
          const idx = allWorks.findIndex((a) => a.id === active.id);
          if (idx !== -1) select(allWorks[(idx + 1) % allWorks.length]);
        } : null}
        onPrev={active ? () => {
          const idx = allWorks.findIndex((a) => a.id === active.id);
          if (idx !== -1) select(allWorks[(idx - 1 + allWorks.length) % allWorks.length]);
        } : null}
      />
    </div>
  );
}

function Discover({ initialArtworkId }) {
  const { t, tv, lang, bodyFont, displayFont } = useLang();
  const [current, setCurrent] = useState(() => {
    if (initialArtworkId) {
      const found = ARTWORKS.find((a) => a.id === initialArtworkId);
      if (found) return found;
    }
    return ARTWORKS[Math.floor(Math.random() * ARTWORKS.length)];
  });

  useEffect(() => {
    window.history.replaceState(null, "", `#/discover/${current.id}`);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [current.id]);

  const shuffle = () => {
    if (ARTWORKS.length <= 1) return;
    let next;
    do {
      next = ARTWORKS[Math.floor(Math.random() * ARTWORKS.length)];
    } while (next.id === current.id);
    setCurrent(next);
  };

  const analysis = ANALYSES[current.id];

  return (
    <div style={{ maxWidth: 900, margin: "0 auto", padding: "48px 24px 100px" }}>
      <h2 style={{ fontFamily: displayFont, fontSize: 32, fontWeight: 700, color: "#221D17", margin: "0 0 24px" }}>
        {t("discoverTitle")}
      </h2>

      <div style={{ marginBottom: 30 }}>
        <button onClick={shuffle} style={{ ...btnPrimary, fontSize: 15, padding: "14px 32px" }}>
          {t("shuffleBtn")}
        </button>
      </div>

      <div style={{ background: "#F7F3EA", border: "1px solid #C9BFA9", borderRadius: 3, overflow: "hidden" }}>
        <ArtImage
          key={current.id}
          sources={[localImageUrl(current.id), current.thumbUrl, current.imageUrl]}
          alt={current.title}
          natural
        />
        <div style={{ padding: 28 }}>
          <div style={{ fontFamily: "'Roboto Mono', monospace", fontSize: 11, color: "#A66B33", direction: "ltr", textAlign: "right", marginBottom: 8 }}>
            {t("catalogNo")} {current.id}
          </div>
          <div style={{ fontFamily: displayFont, fontSize: 26, color: "#221D17", marginBottom: 14 }}>
            {current.title}
          </div>
          <div style={{ display: "flex", flexWrap: "wrap", gap: "6px 20px", fontFamily: bodyFont, fontSize: 14, color: "#3E3A33", marginBottom: analysis ? 22 : 0 }}>
            <span>{t("fieldYear")}: {current.year || t("unknown")}</span>
            <span>{t("fieldSubject")}: {tv(SUBJECT_TR, current.subject)}</span>
            <span>{t("fieldTechnique")}: {current.technique}</span>
            <span>{t("fieldSize")}: {current.sizeDesc}</span>
          </div>

          {analysis && (
            <div style={{ borderTop: "1px solid #C9BFA9", paddingTop: 18 }}>
              <div style={{ fontFamily: bodyFont, fontSize: 12, fontWeight: 700, color: "#3E4A3B", marginBottom: 8, letterSpacing: "0.03em" }}>
                {t("analysisLabel")}
              </div>
              <p style={{ fontFamily: displayFont, fontStyle: "italic", fontSize: 16, lineHeight: 1.8, color: "#221D17", margin: 0 }}>
                {analysis[lang] || analysis.he}
              </p>
              <p style={{ fontFamily: bodyFont, fontSize: 11, color: "#8A7E6C", marginTop: 12 }}>
                {t("analysisDisclaimer")}
              </p>
            </div>
          )}
        </div>
      </div>
    </div>
  );
}


function Contact() {
  const [sent, setSent] = useState(false);
  const [sending, setSending] = useState(false);
  const { t, lang, bodyFont, displayFont } = useLang();
  const contactName = lang === "he" ? "דבורה זילבר" : "Devora Silber";

  const handleSubmit = async (e) => {
    e.preventDefault();
    setSending(true);
    const form = e.target;
    try {
      const res = await fetch(form.action, {
        method: "POST",
        body: new FormData(form),
        headers: { Accept: "application/json" },
      });
      if (res.ok) {
        setSent(true);
        form.reset();
      }
    } catch (err) {
      // fall through — user can retry
    }
    setSending(false);
  };

  return (
    <div style={{ maxWidth: 1000, margin: "0 auto", padding: "48px 24px 100px" }}>
      <h2 style={{ fontFamily: displayFont, fontSize: 32, fontWeight: 700, color: "#221D17", marginBottom: 8 }}>{t("contactTitle")}</h2>
      <p style={{ fontFamily: bodyFont, fontSize: 15, color: "#5F5449", maxWidth: 520, marginBottom: 40 }}>
        {t("contactIntro")}
      </p>
      <div style={{ display: "grid", gridTemplateColumns: "0.9fr 1.1fr", gap: 56 }} className="contact-grid">
        <div style={{ display: "flex", flexDirection: "column", gap: 22 }}>
          <div>
            <div style={{ fontFamily: bodyFont, fontSize: 14, color: "#221D17" }}>{contactName}</div>
            <div style={{ fontFamily: bodyFont, fontSize: 12, color: "#8A7E6C", marginTop: 2 }}>{t("contactRelation")}</div>
          </div>
          <div style={{ display: "flex", gap: 12, alignItems: "center" }}>
            <Phone size={16} color="#A66B33" />
            <span style={{ fontFamily: "'Roboto Mono', monospace", fontSize: 14, color: "#221D17", direction: "ltr" }}>054-563-6612</span>
          </div>
        </div>
        {sent ? (
          <div style={{ fontFamily: bodyFont, fontSize: 15, color: "#3E4A3B", padding: "20px 0" }}>
            {t("formSuccess")}
          </div>
        ) : (
          <form
            action="https://formsubmit.co/silberdeb@gmail.com"
            method="POST"
            onSubmit={handleSubmit}
            style={{ display: "flex", flexDirection: "column", gap: 14 }}
          >
            <input type="hidden" name="_subject" value="פנייה חדשה מאתר אריה ברמץ" />
            <input type="hidden" name="_captcha" value="false" />
            <input
              name="name"
              required
              placeholder={t("formName")}
              style={{ fontFamily: bodyFont, fontSize: 14, padding: "12px 14px", background: "#F7F3EA", border: "1px solid #C9BFA9", borderRadius: 2, color: "#221D17" }}
            />
            <input
              name="email"
              type="email"
              required
              placeholder={t("formEmail")}
              style={{ fontFamily: bodyFont, fontSize: 14, padding: "12px 14px", background: "#F7F3EA", border: "1px solid #C9BFA9", borderRadius: 2, color: "#221D17" }}
            />
            <textarea
              name="message"
              required
              placeholder={t("formMessage")}
              rows={5}
              style={{ fontFamily: bodyFont, fontSize: 14, padding: "12px 14px", background: "#F7F3EA", border: "1px solid #C9BFA9", borderRadius: 2, color: "#221D17", resize: "vertical" }}
            />
            <button type="submit" disabled={sending} style={{ ...btnPrimary, alignSelf: "flex-start", opacity: sending ? 0.6 : 1 }}>
              {sending ? t("formSending") : t("formSubmit")}
            </button>
          </form>
        )}
      </div>
      <style>{`@media (max-width: 700px) { .contact-grid { grid-template-columns: 1fr !important; } }`}</style>
    </div>
  );
}

/* ---------------------------------------------------------
   APP
--------------------------------------------------------- */
function LanguageSwitcher() {
  const { lang, setLang } = useLang();
  const langs = [
    ["he", "HE"],
    ["en", "EN"],
    ["es", "ES"],
  ];
  return (
    <div
      style={{
        display: "flex",
        justifyContent: "center",
        gap: 4,
        padding: "8px 0",
        background: "#221D17",
      }}
    >
      {langs.map(([code, label]) => (
        <button
          key={code}
          onClick={() => setLang(code)}
          style={{
            background: lang === code ? "#F7F3EA" : "transparent",
            color: lang === code ? "#221D17" : "#C9BFA9",
            border: "1px solid #4A4136",
            borderRadius: 3,
            padding: "3px 10px",
            fontFamily: "'Roboto Mono', monospace",
            fontSize: 11,
            fontWeight: 600,
            letterSpacing: "0.04em",
            cursor: "pointer",
          }}
        >
          {label}
        </button>
      ))}
    </div>
  );
}

function parseHash() {
  const h = window.location.hash.replace(/^#\/?/, "");
  const [page, id] = h.split("/");
  const validPages = ["home", "gallery", "selected", "discover", "contact"];
  return { page: validPages.includes(page) ? page : "home", id: id || null };
}

export default function App() {
  const initialRoute = typeof window !== "undefined" ? parseHash() : { page: "home", id: null };
  const [page, setPageState] = useState(initialRoute.page);
  const [initialArtworkId, setInitialArtworkId] = useState(initialRoute.id);
  const [lang, setLang] = useState("he");
  const dir = lang === "he" ? "rtl" : "ltr";
  const t = (key) => (UI[key] ? UI[key][lang] || UI[key].he : key);
  const tvBound = (dict, hebrewValue) => tv(dict, hebrewValue, lang);

  useEffect(() => {
    function onHashChange() {
      const { page: p, id } = parseHash();
      setPageState(p);
      setInitialArtworkId(id);
    }
    window.addEventListener("hashchange", onHashChange);
    return () => window.removeEventListener("hashchange", onHashChange);
  }, []);

  const setPage = (p) => {
    window.location.hash = `/${p}`;
    setPageState(p);
    setInitialArtworkId(null);
  };

  const goToArtwork = (p, id) => {
    window.location.hash = `/${p}/${id}`;
    setPageState(p);
    setInitialArtworkId(id);
  };

  const bodyFont = "'Assistant', sans-serif";
  const displayFont = "'Frank Ruhl Libre', serif";

  return (
    <LanguageContext.Provider value={{ lang, dir, t, tv: tvBound, setLang, bodyFont, displayFont }}>
      <div dir={dir} style={{ background: "#EFE9DD", minHeight: "100vh" }}>
        <style>{`
          @import url('https://fonts.googleapis.com/css2?family=Frank+Ruhl+Libre:wght@500;700&family=Assistant:wght@400;600;700&family=Roboto+Mono:wght@400;500&display=swap');
          * { box-sizing: border-box; }
          input::placeholder, textarea::placeholder { color: #A79A85; }
          .range-thumb { -webkit-appearance: none; appearance: none; height: 28px; }
          .range-thumb::-webkit-slider-thumb {
            -webkit-appearance: none; appearance: none;
            pointer-events: auto; cursor: pointer;
            width: 16px; height: 16px; border-radius: 50%;
            background: #3E4A3B; border: 2px solid #F7F3EA; box-shadow: 0 0 0 1px #C9BFA9;
          }
          .range-thumb::-moz-range-thumb {
            pointer-events: auto; cursor: pointer;
            width: 16px; height: 16px; border-radius: 50%;
            background: #3E4A3B; border: 2px solid #F7F3EA; box-shadow: 0 0 0 1px #C9BFA9;
          }
          .range-thumb::-webkit-slider-runnable-track { background: transparent; }
          .range-thumb::-moz-range-track { background: transparent; }
          body { direction: ${dir}; }
        `}</style>
        <LanguageSwitcher />
        <Nav page={page} setPage={setPage} />
        {page === "home" && <Home setPage={setPage} goToArtwork={goToArtwork} />}
        {page === "gallery" && (
          <Gallery
            artworks={ARTWORKS}
            title={t("galleryTitle")}
            intro={`${ARTWORKS.length} ${t("galleryIntro")}`}
            pageKey="gallery"
            initialArtworkId={initialArtworkId}
          />
        )}
        {page === "selected" && <SelectedWorks initialArtworkId={initialArtworkId} />}
        {page === "discover" && <Discover initialArtworkId={initialArtworkId} />}
        {page === "contact" && <Contact />}
        <div
          style={{
            borderTop: "1px solid #C9BFA9",
            padding: "24px",
            textAlign: "center",
            fontFamily: bodyFont,
            fontSize: 12,
            color: "#8A7E6C",
          }}
        >
          {t("footer")}
        </div>
      </div>
    </LanguageContext.Provider>
  );
}
